#include "menu.h"

#include <stdio.h>

/**
 * menu_write -- desktop output sink (stdout).
 * Input: text NUL-terminated string. Returns: nothing. Side effect: writes to stdout.
 */
void menu_write(const char *text)
{
    fputs(text, stdout);
}

/**
 * show_call -- print one callback invocation.
 * Input: name function name, ctx captured parameters. Returns: 0.
 */
static int show_call(const char *name, const MenuCommandContext *ctx)
{
    int i;

    printf("[callback] %s argc=%d", name, ctx->argc);
    for (i = 0; i < ctx->argc; i++) {
        printf(" argv[%d]=%s", i, ctx->argv[i]);
    }
    printf("\n");
    return 0;
}

/**
 * cli_version -- desktop stub for "VERSION".
 * Input: ctx captured parameters. Returns: 0.
 */
int cli_version(const MenuCommandContext *ctx)
{
    return show_call("cli_version", ctx);
}

